<script setup>
// Code tab: the selection (or the page) as Design JSX, React + Tailwind or HTML, generated by
// OpenPencil's own code formats and kept up to date while you edit. Read-only, with Copy.
import { computed, onUnmounted, ref, watch } from 'vue';
import { Check, Copy } from 'lucide-vue-next';
import { useEditor } from '@open-pencil/vue';
import { generateCode } from './io.js';
import { t } from './l10n.js';

const props = defineProps({ active: Boolean });
const editor = useEditor();
const FORMATS = [
  { value: 'jsx', label: 'Design JSX' },
  { value: 'tailwind-jsx', label: 'React + Tailwind' },
  { value: 'html', label: 'HTML + CSS' },
];
const format = ref('tailwind-jsx');
const code = ref(''), error = ref(''), copied = ref(false);
const scope = computed(() => (editor.state.selectedIds.size ? t('所选图层', 'Selection') : t('当前页面', 'Page')));
let timer, run = 0;

async function refresh() {
  const mine = ++run, ids = [...editor.state.selectedIds];
  const target = ids.length ? { scope: 'selection', nodeIds: ids } : { scope: 'page', pageId: editor.state.currentPageId };
  try {
    const text = await generateCode(editor, format.value, target);
    if (mine === run) { code.value = text.trim(); error.value = ''; }
  } catch (e) { if (mine === run) { code.value = ''; error.value = String(e?.message ?? e); } }
}
// Only while the tab is visible; edits are debounced so typing on the canvas stays smooth.
watch(() => [props.active, format.value, editor.state.sceneVersion, editor.state.selectedIds, editor.state.currentPageId], () => {
  if (!props.active) return;
  clearTimeout(timer); timer = setTimeout(refresh, 150);
}, { immediate: true });
onUnmounted(() => clearTimeout(timer));

async function copy() {
  await navigator.clipboard.writeText(code.value).catch(() => {});
  copied.value = true; setTimeout(() => { copied.value = false; }, 1200);
}
</script>

<template>
  <div class="op-panel-body op-code" data-testid="code-panel">
    <div class="op-code-bar">
      <select v-model="format" class="op-select" style="flex: 1" data-testid="code-format" :aria-label="t('代码格式', 'Code format')">
        <option v-for="f in FORMATS" :key="f.value" :value="f.value">{{ f.label }}</option>
      </select>
      <button class="btn" :disabled="!code" :title="t('复制代码', 'Copy code')" @click="copy"><Check v-if="copied" /><Copy v-else />{{ copied ? t('已复制', 'Copied') : t('复制', 'Copy') }}</button>
    </div>
    <div class="muted op-code-scope">{{ scope }}</div>
    <p v-if="error" class="op-message">{{ error }}</p>
    <pre v-else class="op-code-view" data-testid="code"><code>{{ code || t('页面是空的。', 'The page is empty.') }}</code></pre>
  </div>
</template>
